<title>Pomofocus</title>
<style>
*{box-sizing:border-box}
html,body{margin:0;width:100%;min-height:100%;font-family:Arial,Helvetica,sans-serif;color:#fff;background:#b63d4e}
button,input{font:inherit}
button{cursor:pointer}
.btn{cursor:pointer}
.app{width:100%;min-height:100vh;background:#b63d4e;transition:background .25s}
.app.break{background:#8e676a}
.app.long{background:#3f9292}
header{height:31px;padding:7px 6px 0;display:flex;align-items:flex-start;justify-content:space-between;font-size:10px;font-weight:bold}
.brand{display:flex;align-items:center;gap:2px}
.brand:before{content:"●";font-size:10px}
.header-actions{display:flex;gap:4px}
.header-actions button{border:0;background:rgba(255,255,255,.2);color:#fff;width:16px;height:17px;padding:0;border-radius:2px;font-size:10px;font-weight:bold;line-height:17px}
main{padding:11px 6px 0}
.timer-box{background:rgba(255,255,255,.12);border-radius:3px;padding:10px 6px 12px;text-align:center}
.mode-tabs{height:19px;display:flex;justify-content:center;gap:12px;font-size:8px;align-items:center}
.mode-tabs button{border:0;color:#fff;background:none;padding:3px 4px;border-radius:3px;font-size:8px}
.mode-tabs button.active{background:rgba(105,25,40,.32);font-weight:bold}
.time{font-size:49px;line-height:58px;font-weight:bold;letter-spacing:-1px;margin:3px 0 7px}
.start{background:#fff;color:#ae3547;border:0;border-radius:2px;width:100px;height:31px;font-size:11px;font-weight:bold}
.timer-extra{height:0;position:relative}
.skip{position:absolute;right:8px;top:-24px;background:none;border:0;color:#fff;font-size:14px;display:none}
.running .skip{display:block}
.counter{text-align:center;font-size:8px;line-height:13px;margin-top:8px;min-height:26px}
.tasks-head{height:26px;margin-top:2px;border-bottom:1px solid rgba(255,255,255,.75);display:flex;justify-content:space-between;align-items:center;font-size:10px;font-weight:bold}
.menu{border:0;background:rgba(255,255,255,.19);color:#fff;border-radius:2px;width:16px;height:17px;font-weight:bold;line-height:12px}
.task-menu{position:absolute;right:6px;top:95px;background:#fff;color:#444;width:148px;z-index:10;box-shadow:0 2px 5px #73313a;display:none;font-size:10px}
.task-menu.show{display:block}
.task-menu button{display:block;width:100%;text-align:left;border:0;background:#fff;color:#444;padding:8px}
.task-menu button:hover{background:#eee}
.task-area{position:relative}
.add-task{margin-top:8px;height:34px;width:100%;border:1px dashed rgba(255,255,255,.7);border-radius:4px;background:transparent;color:#fff;font-size:10px}
.add-task strong{font-size:12px}
.editor{margin-top:8px;background:#fff;color:#555;border-radius:4px;overflow:hidden;box-shadow:0 1px 3px #87313e;display:none}
.editor.open{display:block}
.editor input{width:calc(100% - 14px);margin:10px 7px 6px;border:1px solid #eee;padding:7px 5px;height:28px;color:#555;font-size:11px}
.editor label{display:block;margin:0 7px 4px;font-size:8px}
.pomo-controls{display:flex;gap:4px;margin:0 7px 7px}
.pomo-controls input{width:38px;height:20px;margin:0;text-align:center;padding:0}
.pomo-controls button{width:20px;height:20px;border:1px solid #ddd;background:#fafafa;color:#777;border-radius:4px;font-size:9px}
.editor-links{font-size:8px;color:#999;margin:4px 7px 9px;text-decoration:underline}
.editor-footer{background:#f4f4f4;height:38px;display:flex;justify-content:flex-end;align-items:center;gap:8px;padding:0 7px}
.cancel{border:0;background:transparent;color:#888;font-size:8px}
.save{border:0;background:#42454c;color:#fff;border-radius:4px;font-size:8px;padding:6px 10px}
.task-list{margin-top:8px}
.task{background:#fff;color:#555;min-height:35px;border-radius:3px;margin-bottom:5px;padding:9px 7px;display:flex;align-items:center;justify-content:space-between;font-size:9px;border-left:3px solid #963444}
.task.done{opacity:.65;text-decoration:line-through;border-left-color:#e98d98}
.task-left{display:flex;align-items:center;gap:5px;min-width:0}
.check{width:13px;height:13px;border-radius:50%;border:1px solid #ddd;background:#fff;color:#fff;padding:0;font-size:9px;line-height:11px}
.done .check{background:#d67885;border-color:#d67885}
.task-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.task-count{font-size:8px;color:#888}
.stats{background:rgba(255,255,255,.12);height:38px;margin-top:9px;display:flex;align-items:center;justify-content:center;font-size:8px;color:#f3dfe1}
.stats b{font-size:12px;color:#fff;margin:0 2px}
.info{background:#fff;color:#56222a;margin:12px -6px 0;padding:13px 6px;min-height:180px}
.info h2{font-size:13px;line-height:17px;margin:0 0 17px}
.info h3{font-size:11px;margin:0 0 8px}
.info h3:after{content:"";display:block;width:13px;border-bottom:2px solid #e78a94;margin-top:5px}
.info p{color:#777;font-size:8px;line-height:12px;margin:0}
.info em{color:#b43d4d;font-style:normal;font-weight:bold}
.toast{position:fixed;bottom:10px;left:50%;transform:translateX(-50%);background:#fff;color:#444;border-radius:4px;padding:10px;width:200px;box-shadow:0 2px 8px #83303b;display:none;font-size:9px;z-index:30}
.toast.show{display:flex;justify-content:space-between;align-items:center}
.toast button{background:#57ad91;color:white;border:0;border-radius:3px;padding:6px;font-size:8px}
.confetti{position:fixed;inset:0;pointer-events:none;display:none;overflow:hidden}
.confetti.show{display:block}
.confetti i{position:absolute;width:4px;height:2px;animation:fall 1.4s linear forwards}
@keyframes fall{0%{transform:translateY(-10px) rotate(0)}100%{transform:translateY(470px) rotate(720deg)}}
@media(min-width:500px){
  .app{max-width:644px;margin:auto}
  header{height:45px;padding:12px 14px;font-size:14px}
  .brand:before{font-size:14px}.header-actions{gap:7px}.header-actions button{width:24px;height:24px;font-size:14px}
  main{padding:20px 14px}.timer-box{padding:18px 12px 20px}.mode-tabs{font-size:12px;height:28px}.mode-tabs button{font-size:12px}
  .time{font-size:78px;line-height:90px}.start{width:150px;height:45px;font-size:15px}
  .counter,.tasks-head{font-size:13px}.tasks-head{height:38px}.add-task{height:52px;font-size:13px}
  .info{margin:20px -14px 0;padding:25px 14px}.info h2{font-size:18px}.info h3{font-size:15px}.info p{font-size:12px;line-height:18px}
}
</style>
</head>
<body>
<div class="app" id="app">
<header>
  <div class="brand">Pomofocus</div>
  <div class="header-actions">
    <button class="btn" title="Statistics">▥</button>
    <button class="btn" title="Settings">⚙</button>
    <button class="btn" title="Login">●</button>
    <button class="btn" title="More">⋮</button>
  </div>
</header>
<main>
  <section class="timer-box">
    <nav class="mode-tabs">
      <button class="btn active" data-mode="pomodoro">Pomodoro</button>
      <button class="btn" data-mode="short">Short Break</button>
      <button class="btn" data-mode="long">Long Break</button>
    </nav>
    <div class="time" id="time">25:00</div>
    <button class="btn start" id="start">START</button>
    <div class="timer-extra"><button class="btn skip" id="skip">▶</button></div>
  </section>
  <div class="counter" id="counter">#1<br><span>Time to focus!</span></div>
  <section class="task-area">
    <div class="tasks-head"><span>Tasks</span><button class="btn menu" id="menu">⋮</button></div>
    <div class="task-menu" id="taskMenu">
      <button class="btn" id="clearFinished">▣ &nbsp; Clear finished tasks</button>
      <button class="btn">✓ &nbsp; Clear act pomodoros</button>
      <button class="btn">▣ &nbsp; Save as routine</button>
      <button class="btn">＋ &nbsp; Add from routines</button>
      <button class="btn">⇄ &nbsp; Import from Todoist</button>
      <button class="btn" id="clearAll">▣ &nbsp; Clear all tasks</button>
    </div>
    <button class="btn add-task" id="addTask"><strong>⊕</strong> Add Task</button>
    <div class="editor" id="editor">
      <input id="taskInput" placeholder="What are you working on?">
      <label>Est Pomodoros</label>
      <div class="pomo-controls"><input value="1"><button class="btn">⌃</button><button class="btn">⌄</button></div>
      <div class="editor-links">＋ Add Note &nbsp; ＋ Add Project &nbsp; ▪</div>
      <div class="editor-footer"><button class="btn cancel" id="cancel">Cancel</button><button class="btn save" id="save">Save</button></div>
    </div>
    <div class="task-list" id="taskList"></div>
    <div class="stats" id="stats" style="display:none">Pomos: <b>0</b> / 1 &nbsp;&nbsp; Finish at: <b>14:57</b> (0.4h)</div>
  </section>
  <section class="info">
    <h2>An online Pomodoro Timer to boost<br>your productivity</h2>
    <h3>What is Pomofocus?</h3>
    <p>Pomofocus is a customizable pomodoro timer that works on desktop &amp; mobile browser. The aim of this app is to help you focus on any task you are working on, such as study, writing, or coding. This app is inspired by <em>Pomodoro Technique</em> which is a time management method developed by Francesco Cirillo.</p>
  </section>
</main>
<div class="toast" id="toast"><span>You've finished all your tasks for today 🎉</span><button class="btn" id="toastClear">Clear Tasks</button></div>
<div class="confetti" id="confetti"></div>
</div>
<script>
const app=document.getElementById('app'),timeEl=document.getElementById('time'),start=document.getElementById('start'),counter=document.getElementById('counter'),editor=document.getElementById('editor'),input=document.getElementById('taskInput'),list=document.getElementById('taskList');
let mode='pomodoro',seconds=1500,running=false,interval=null,tasks=[];
const durations={pomodoro:1500,short:300,long:900};
function fmt(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function setMode(m){
 mode=m; seconds=durations[m]; running=false; clearInterval(interval); app.className='app '+(m==='short'?'break':m==='long'?'long':'');
 timeEl.textContent=fmt(seconds);start.textContent='START';
 document.querySelectorAll('.mode-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));
 counter.innerHTML='#1<br><span>'+ (m==='pomodoro'?'Time to focus!':'Time for a break!')+'</span>';
}
document.querySelectorAll('.mode-tabs button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
start.onclick=()=>{
 running=!running; start.textContent=running?'PAUSE':'START'; app.classList.toggle('running',running);
 if(running){interval=setInterval(()=>{if(seconds>0){seconds--;timeEl.textContent=fmt(seconds)}else{clearInterval(interval);running=false;start.textContent='START'}},1000)}
 else clearInterval(interval);
};
document.getElementById('skip').onclick=()=>setMode(mode);
document.getElementById('addTask').onclick=()=>{editor.classList.add('open');input.focus()};
document.getElementById('cancel').onclick=()=>editor.classList.remove('open');
document.getElementById('save').onclick=()=>{
 let name=input.value.trim()||'123'; tasks.push({name,done:false}); input.value=''; editor.classList.remove('open'); render();
};
function render(){
 list.innerHTML='';
 tasks.forEach((t,i)=>{
  let row=document.createElement('div');row.className='task '+(t.done?'done':'');
  row.innerHTML='<div class="task-left"><button class="btn check">'+(t.done?'✓':'')+'</button><span class="task-name">'+t.name+'</span></div><span class="task-count">0 / 1 &nbsp;⋮</span>';
  row.querySelector('.check').onclick=()=>{t.done=!t.done;render(); if(t.done&&tasks.every(x=>x.done))showToast()};
  list.appendChild(row);
 });
 document.getElementById('stats').style.display=tasks.length?'block':'none';
}
const menu=document.getElementById('taskMenu');
document.getElementById('menu').onclick=()=>menu.classList.toggle('show');
document.getElementById('clearFinished').onclick=()=>{tasks=tasks.filter(t=>!t.done);menu.classList.remove('show');render()};
document.getElementById('clearAll').onclick=()=>{tasks=[];menu.classList.remove('show');render()};
function showToast(){document.getElementById('toast').classList.add('show');let c=document.getElementById('confetti');c.innerHTML='';for(let i=0;i<30;i++){let x=document.createElement('i');x.style.left=Math.random()*100+'%';x.style.top=Math.random()*30+'%';x.style.background=['#f4ce42','#43b9c5','#e76d83','#fff'][i%4];x.style.animationDelay=Math.random()*.5+'s';c.appendChild(x)}c.classList.add('show')}
document.getElementById('toastClear').onclick=()=>{tasks=[];render();document.getElementById('toast').classList.remove('show');document.getElementById('confetti').classList.remove('show')};
</script>
</body>
</html>
